const E=R.e, I=R.icon;
R.logo = (light=false) => `<button class="wordmark ${light?'light':''}" data-action="home" aria-label="Relay home"><span class="relay-mark"><b></b><b></b></span>relay<span class="wordmark-dot">.</span></button>`;
R.btn = (text,action,cls='btn',extra='') => `<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
R.newButton = (text='Leave a handoff',extra='') => R.btn(`${I('plus')}${text}`,'new','btn primary',extra);
R.bookmark = c => `<button class="icon-btn bookmark ${c.saved?'is-saved':''}" data-bookmark="${E(c.id)}" aria-label="${c.saved?'Remove bookmark':'Bookmark handoff'}" aria-pressed="${!!c.saved}">${I('bookmark')}</button>`;
R.projectMark = project => `<span class="project-mark p${Math.max(0,R.data.projects.indexOf(project))%4}">${E(project.slice(0,1))}</span>`;
R.tag = c => `<span class="tag ${c.type.toLowerCase()}">${c.type==='Bug'?'<span class="tiny-square"></span>':''}${E(c.type)}</span>`;
R.status = c => `<span class="status status-${c.status}"><i></i>${R.statuses[c.status]}</span>`;
R.search = (placeholder='Search your context…') => `<label class="search-box">${I('search')}<input data-search aria-label="Search handoffs" placeholder="${placeholder}" value="${E(R.ui.query)}"><kbd>/</kbd></label>`;
R.typeFilters = () => `<div class="type-filters" aria-label="Filter by type">${['all','Feature','Bug','Exploration'].map(t=>`<button data-type="${t}" class="${R.ui.type===t?'selected':''}" aria-pressed="${R.ui.type===t}">${t==='all'?'All types':t==='Exploration'?'Explorations':t+'s'}</button>`).join('')}</div>`;
R.projectOptions = (selected,all=true) => `${all?'<option value="">All projects</option>':''}${R.data.projects.map(p=>`<option value="${E(p)}" ${p===selected?'selected':''}>${E(p)}</option>`).join('')}`;
R.projectSelect = () => `<label class="project-select">${I('folder')}<select data-project-select aria-label="Select project">${R.projectOptions(R.ui.project)}</select>${I('down')}</label>`;
R.folderSelect = () => `<label class="folder-select"><span class="sr-only">Folder</span><select data-folder-select aria-label="Filter by folder"><option value="">All folders</option>${R.data.folders.filter(f=>!R.ui.project||f.project===R.ui.project).map(f=>`<option value="${E(f.id)}" ${R.ui.folder===f.id?'selected':''}>${E(R.ui.project?f.name:f.project+' / '+f.name)}</option>`).join('')}</select></label>`;
R.mobileTools = () => `<div class="mobile-organizer">${R.projectSelect()}${R.folderSelect()}${R.btn(I('plus'),'organize','icon-btn','aria-label="Create project or folder"')}</div>`;
R.scopeNav = () => [['all','grid','All threads'],['saved','bookmark','Bookmarked'],['archive','archive','Archive']].map(([key,icon,label])=>`<button class="side-nav-item ${R.ui.scope===key&&!R.ui.project?'active':''}" data-scope="${key}">${I(icon)}<span>${label}</span><small>${R.data.cards.filter(c=>key==='archive'?c.archived:key==='saved'?c.saved&&!c.archived:!c.archived).length}</small></button>`).join('');
R.tree = () => R.data.projects.map(p=>`<div class="tree-project"><button class="project-row ${R.ui.project===p&&!R.ui.folder?'active':''}" data-project="${E(p)}">${R.projectMark(p)}<span>${E(p)}</span><small>${R.data.cards.filter(c=>c.project===p&&!c.archived).length}</small></button><div class="folder-tree">${R.data.folders.filter(f=>f.project===p).map(f=>`<button class="folder-row ${R.ui.folder===f.id?'active':''}" data-folder="${E(f.id)}">${I('folder')}<span>${E(f.name)}</span></button>`).join('')}</div></div>`).join('');
R.sidebar = () => `<aside class="side-panel">${R.logo()}<div class="personal-space"><span>PERSONAL WORKSPACE</span><span class="local-dot"></span></div><nav class="scope-nav" aria-label="Your handoffs">${R.scopeNav()}</nav><div class="side-section-label">PROJECTS & FOLDERS<button class="icon-btn" data-action="organize" aria-label="Add a project or folder">${I('plus')}</button></div><nav class="project-tree" aria-label="Projects and folders">${R.tree()}</nav><div class="side-bottom"><button data-action="research">${I('info')}Behind the idea <span>↗</span></button><button data-action="backup">${I('export')}Export & backup</button><div class="local-profile"><span class="profile-initial">Y</span><div>Your workspace<small>Saved in this browser</small></div></div></div></aside>`;
R.files = c => `<div class="file-list">${c.files.map(f=>`<button class="file-reference" data-reference="${E(f)}" title="View and copy file reference">${I('file')}<span>${E(f)}</span>${I('arrow')}</button>`).join('')}${c.links?c.links.split('\n').filter(Boolean).map(url=>{let valid=false;try{valid=['https:','http:'].includes(new URL(url).protocol);}catch{}return valid?`<a class="file-reference" href="${E(url)}" target="_blank" rel="noopener noreferrer">${I('link')}<span>${E(url)}</span>↗</a>`:`<span class="file-reference">${I('link')}${E(url)}</span>`;}).join(''):''}</div>`;
R.noteSections = (c,compact=false) => `<div class="note-section"><span class="section-eyebrow">${I('clock')}LAST THING TRIED</span><p>${E(c.tried||'No previous attempt recorded. A fresh place to start.')}</p></div><div class="next-action ${compact?'compact':''}"><span class="section-eyebrow">${I('arrow')}YOUR NEXT STEP</span><p>${E(c.next)}</p></div>${c.blocked?`<div class="blocker"><span class="blocker-dot"></span><div><strong>Blocked by</strong><p>${E(c.blocked)}</p></div></div>`:''}`;
R.empty = (text='No threads here yet.',sub='Leave a little context for the next time you return.') => `<div class="empty-state"><span class="empty-glyph">${I('lines')}</span><h3>${text}</h3><p>${sub}</p>${R.newButton('Start a thread')}</div>`;
R.detail = (c,embedded=false) => c ? `<article class="reader ${embedded?'embedded':''}"><div class="reader-topline"><span class="mono">${E(c.project)} / ${E(R.data.folders.find(f=>f.id===c.folder)?.name||'Unfiled')}</span>${R.bookmark(c)}</div><div class="reader-meta">${R.tag(c)}${R.status(c)}<time>${R.age(c.updated)}</time></div><h2 ${embedded?'':'id="modal-title"'}>${E(c.title)}</h2><div class="branch-line">${I('branch')}<code>${E(c.branch||'No branch reference')}</code></div>${R.noteSections(c)}${c.files.length||c.links?`<section class="context-files"><span class="section-eyebrow">ATTACHED CONTEXT</span>${R.files(c)}<small>File references are saved notes. Editor connection comes later.</small></section>`:''}<div class="reader-actions">${R.btn(`${I('edit')}Leave a checkpoint`,'edit','btn primary',`data-id="${E(c.id)}"`)}<label class="status-select-label"><span class="sr-only">Thread status</span><select data-status-id="${E(c.id)}" aria-label="Thread status">${Object.entries(R.statuses).map(([k,v])=>`<option value="${k}" ${c.status===k?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="reader-secondary">${R.btn(`${I('export')}Export note`,'export-card','text-btn',`data-id="${E(c.id)}"`)}${R.btn(`${I(c.archived?'restore':'archive')}${c.archived?'Restore thread':'Archive thread'}`,'archive-card','text-btn',`data-id="${E(c.id)}"`)}<span>${c.history.length} earlier checkpoint${c.history.length===1?'':'s'}</span></div><details class="checkpoint-history"><summary>${I('clock')}Earlier checkpoints <span>${c.history.length}</span></summary>${c.history.length?c.history.map(h=>`<div class="checkpoint"><time>${R.date(h.at,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</time><strong>${E(h.reason||'Earlier checkpoint')}</strong><p>${E(h.tried||'No attempt recorded.')}</p><p><b>Next:</b> ${E(h.next)}</p>${h.blocked?`<p><b>Blocked:</b> ${E(h.blocked)}</p>`:''}</div>`).join(''):'<p class="history-empty">Your earlier reasoning will appear here when you save a checkpoint.</p>'}</details></article>` : R.empty('Nothing selected.','Choose a thread, or start something new.');
R.smallCard = c => `<article class="small-card"><div class="small-card-head"><span>${R.projectMark(c.project)}${E(c.project)}</span>${R.bookmark(c)}</div><button class="small-card-open" data-open="${E(c.id)}"><h3>${E(c.title)}</h3><p>${E(c.next)}</p></button><div class="small-card-foot">${R.tag(c)}<span>${R.age(c.updated)}</span>${I('arrow')}</div></article>`;
R.topbar = () => `<header class="app-topbar"><div class="breadcrumbs">Workspace<span>/</span><strong>${E(R.scopeTitle())}</strong></div><div class="topbar-actions"><span class="prototype-label"><i></i>LOCAL CONCEPT</span>${R.btn(I('info'),'research','icon-btn','aria-label="Research and design notes"')}${R.newButton()}</div></header>`;
R.desk = () => {
 const cards=R.cards(),latest=cards[0],other=cards.slice(1);
 return `<div class="desk-layout">${R.sidebar()}<div class="desk-main">${R.topbar()}<main id="main" class="desk-content">${R.mobileTools()}<section class="desk-intro"><div><span class="eyebrow">${R.date(Date.now(),{weekday:'long',day:'numeric',month:'long'}).toUpperCase()} · A FRESH PLACE TO START</span><h1>Back to the good part<span>.</span></h1><p>Your work is here. So is the thinking behind it.</p></div><div class="desk-thread" aria-hidden="true"><svg viewBox="0 0 230 110"><path d="M10 85C60 85 35 25 85 25S110 95 157 95 170 20 220 20" fill="none" stroke="#dde5d3" stroke-width="20"/><path d="M10 85C60 85 35 25 85 25S110 95 157 95 170 20 220 20" fill="none" stroke="#749164" stroke-width="1.5" stroke-dasharray="3 5"/><circle cx="10" cy="85" r="5" fill="#3b5b38"/><circle cx="220" cy="20" r="5" fill="#3b5b38"/></svg><span>Pick up the thread.</span></div></section><div class="desk-section-head"><h2>${R.ui.query?'Matching your search':R.ui.scope==='archive'?'A little room to breathe':'Right where you left it'}</h2><span>${E(R.scopeTitle())}</span></div><div class="desk-feature-grid"><section>${latest?`<article class="desk-feature"><div class="feature-project"><span>${R.projectMark(latest.project)}${E(latest.project)}<i>/</i><code>${E(latest.branch||'No branch')}</code></span>${R.bookmark(latest)}</div><div class="feature-body"><div class="feature-meta">${R.tag(latest)}${R.status(latest)}<span>${R.age(latest.updated)}</span></div><h2>${E(latest.title)}</h2>${R.noteSections(latest)}<div class="feature-files">${latest.files.slice(0,2).map(f=>`<button data-reference="${E(f)}">${I('file')}${E(f)}</button>`).join('')}</div></div><div class="feature-footer"><span>${I('check')}Your context, kept close.</span>${R.btn(`Pick up here ${I('arrow')}`,'open','btn primary',`data-id="${E(latest.id)}"`)}</div></article>`:R.empty()}</section><aside class="desk-margin"><div class="ritual"><span class="eyebrow">BEFORE YOU SWITCH AWAY</span><h2>A small note.<br>A softer landing.</h2><p>Save what you learned.<br>Leave one thing to try next.</p><div class="ritual-prompts"><span><b>01</b>What was the goal?</span><span><b>02</b>What did you try?</span><span><b>03</b>Where would you start?</span></div>${R.btn(`Leave yourself a handoff ${I('arrow')}`,'new','text-btn')}<span class="ritual-asterisk" aria-hidden="true">✳</span></div><div class="desk-projects"><div class="mini-section-title">YOUR PROJECTS ${R.btn(I('plus'),'organize','icon-btn','aria-label="Add project or folder"')}</div>${R.data.projects.map(p=>`<button data-project="${E(p)}">${R.projectMark(p)}<span>${E(p)}</span>${I('arrow')}</button>`).join('')}</div></aside></div><section class="desk-open-threads"><div class="collection-toolbar"><div><h2>The other open threads</h2><p>Keep the context. Lose the mental tabs.</p></div>${R.search()}</div><div class="collection-filters">${R.typeFilters()}<span>${cards.length} thread${cards.length===1?'':'s'} · latest first</span></div><div class="desk-card-grid">${other.length?other.map(R.smallCard).join(''):'<p class="muted small">No other threads in this view.</p>'}</div></section><footer class="desk-footer"><b>relay.</b><span>A little context goes a long way.</span><button data-action="research">Read the thinking behind this concept ↗</button></footer></main></div></div>`;
};
R.index = () => {
 const cards=R.cards(),current=R.current();
 return `<div class="index-layout">${R.sidebar()}<section class="index-middle"><header><span class="mono">THREAD INDEX</span>${R.btn(I('plus'),'new','icon-btn','aria-label="New handoff"')}</header><div class="index-title"><h1>${E(R.scopeTitle())}<small>${cards.length}</small></h1><p>A place for every loose end.</p></div>${R.mobileTools()}${R.search('Find a thread or file…')}<div class="index-filter"><label>SHOW<select data-type-select aria-label="Filter by type"><option value="all">All types</option>${['Feature','Bug','Exploration'].map(t=>`<option ${R.ui.type===t?'selected':''}>${t}</option>`).join('')}</select></label><span>UPDATED ↓</span></div><nav class="index-list" aria-label="Handoffs">${cards.length?cards.map(c=>`<button class="index-item ${current?.id===c.id?'active':''}" data-select="${E(c.id)}"><div>${R.status(c)}<time>${R.age(c.updated)}</time></div><h2>${E(c.title)}</h2><p>${E(c.next)}</p><span class="index-item-bottom">${I(c.type==='Bug'?'settings':'file')}${E(c.project)}<span>${c.type}</span></span></button>`).join(''):'<div class="list-empty">No matching threads. Change your filters or leave a new handoff.</div>'}</nav><div class="index-list-footer">${I('check')}Saved locally · ${R.btn('New thread','new','text-btn')}</div></section><main class="index-reader" id="main"><header class="index-reader-bar"><span>${I('file')}CONTEXT / ${current?'READING':'EMPTY'}</span><div>${R.btn(I('search'),'search','icon-btn','aria-label="Focus search"')}${R.btn(I('info'),'research','icon-btn','aria-label="Research and design notes"')}</div></header>${R.detail(current,true)}</main></div>`;
};
R.board = () => {
 const cards=R.cards();
 return `<div class="board-layout"><header class="board-header">${R.logo()}<nav aria-label="Project">${R.btn('All projects','all-projects',`board-project ${!R.ui.project?'active':''}`)}${R.data.projects.map(p=>`<button data-project="${E(p)}" class="board-project ${R.ui.project===p?'active':''}">${E(p)}</button>`).join('')}${R.btn(I('plus'),'organize','icon-btn','aria-label="Add project or folder"')}</nav><div class="board-header-right">${R.btn(I('info'),'research','icon-btn','aria-label="Research and design notes"')}<span class="profile-initial">Y</span></div></header><main id="main" class="board-content"><div class="board-intro"><div><span class="mono">RELAY / WORK IN PROGRESS</span><h1>Your work, in motion<span>↗</span></h1><p>A clear view of what’s next, what’s moving, and what needs a hand.</p></div>${R.newButton('New thread')}</div><div class="board-toolbar"><div class="board-scope-tabs">${[['all','Active threads'],['saved','Bookmarked'],['archive','Archive']].map(([key,label])=>`<button data-board-scope="${key}" class="${R.ui.scope===key?'active':''}">${label}</button>`).join('')}</div><div class="board-tools">${R.search('Find a thread…')}<select data-type-select aria-label="Filter by type"><option value="all">All types</option>${['Feature','Bug','Exploration'].map(t=>`<option ${R.ui.type===t?'selected':''}>${t}</option>`).join('')}</select>${R.btn(`${I('folder')}Folders`,'organize','btn subtle')}</div></div><div class="board-folder-strip">${R.ui.folder?R.btn(`${I('close')}Clear folder filter`,'clear-folder','text-btn'):''}${R.data.folders.filter(f=>!R.ui.project||f.project===R.ui.project).map(f=>`<button data-folder="${E(f.id)}" class="${R.ui.folder===f.id?'selected':''}">${I('folder')}${E(f.name)}</button>`).join('')}</div><section class="kanban" aria-label="Threads by status">${Object.entries(R.statuses).map(([key,label],i)=>{const lane=cards.filter(c=>c.status===key);return `<section class="board-lane" data-drop-status="${key}" aria-label="${label}"><header><span class="lane-icon lane-${key}">${['○','◔','!','✓'][i]}</span><h2>${label}</h2><span class="lane-count">${lane.length}</span><button class="icon-btn" data-action="new" data-new-status="${key}" aria-label="Add thread to ${label}">${I('plus')}</button></header><div class="lane-cards">${lane.map(c=>`<article class="board-card" draggable="true" data-drag-id="${E(c.id)}"><div class="board-card-meta">${R.tag(c)}${R.bookmark(c)}</div><button class="board-card-open" data-open="${E(c.id)}"><h3>${E(c.title)}</h3><div class="board-card-next"><span>NEXT</span><p>${E(c.next)}</p></div>${c.blocked&&c.status==='blocked'?`<p class="board-card-blocker">${E(c.blocked)}</p>`:''}</button><div class="board-card-context">${I('branch')}<code>${E(c.branch||'No branch')}</code></div><div class="board-card-bottom"><span>${R.projectMark(c.project)}${E(c.project)}</span><span>${R.age(c.updated)}</span></div><label class="board-move"><span>Move to</span><select data-status-id="${E(c.id)}" aria-label="Move ${E(c.title)} to status">${Object.entries(R.statuses).map(([k,v])=>`<option value="${k}" ${c.status===k?'selected':''}>${v}</option>`).join('')}</select></label></article>`).join('')}<button class="lane-add" data-action="new" data-new-status="${key}">${I('plus')}${lane.length?'Add a thread':'Leave the first thread'}</button></div></section>`;}).join('')}</section><div class="board-footnote"><span>${I('info')}Drag a card to move it. The “Move to” menu works with keyboard and touch.</span>${R.btn(`${I('export')}Export workspace`,'backup','text-btn')}</div></main></div>`;
};
R.journal = () => {
 const cards=R.cards(),groups=new Map();cards.forEach(c=>{const label=R.date(c.updated,{day:'numeric',month:'long',year:'numeric'});if(!groups.has(label))groups.set(label,[]);groups.get(label).push(c);});
 return `<div class="journal-layout"><header class="journal-header"><div class="journal-brand">${R.logo()}<span>THE WORKING JOURNAL</span></div><nav>${R.btn('Entries','journal-all',R.ui.scope==='all'?'active':'')}${R.btn('Kept pages','journal-saved',R.ui.scope==='saved'?'active':'')}${R.btn('Archive','journal-archive',R.ui.scope==='archive'?'active':'')}${R.btn('About this idea ↗','research')}</nav>${R.newButton('Write an entry')}</header><main id="main" class="journal-main"><aside class="journal-margin"><span class="mono">YOUR NOTEBOOKS</span><button data-action="all-projects" class="journal-project ${!R.ui.project?'active':''}"><span>00</span>Everywhere</button>${R.data.projects.map((p,i)=>`<button data-project="${E(p)}" class="journal-project ${R.ui.project===p?'active':''}"><span>0${i+1}</span>${E(p)}</button>`).join('')}${R.btn(`${I('plus')}New notebook / folder`,'organize','text-btn')}<div class="journal-folder-list">${R.data.folders.filter(f=>!R.ui.project||f.project===R.ui.project).map(f=>`<button data-folder="${E(f.id)}" class="${R.ui.folder===f.id?'active':''}">${I('folder')}${E(f.name)}</button>`).join('')}${R.ui.folder?R.btn('Clear folder filter','clear-folder','text-btn'):''}</div><div class="journal-margin-note"><span class="handwritten">Leave a breadcrumb.</span><p>The thinking matters<br>as much as the doing.</p><svg viewBox="0 0 90 90" aria-hidden="true"><path d="M10 10c50-10 75 40 35 50S20 25 60 38s23 24 10 41m-7-5 7 6 6-7" fill="none" stroke="currentColor" stroke-width="1.5"/></svg></div>${R.btn(`${I('export')}Export & backup`,'backup','text-btn')}</aside><section class="journal-pages">${R.mobileTools()}<div class="journal-title"><span class="eyebrow">AN ONGOING RECORD OF MAKING THINGS</span><h1>Notes for<br><em>the next time.</em></h1><p>The attempts, the loose ends, the way forward.</p></div><div class="journal-tools">${R.search('Find a thought…')}<select data-type-select aria-label="Filter entries by type"><option value="all">Every kind of work</option>${['Feature','Bug','Exploration'].map(t=>`<option ${R.ui.type===t?'selected':''}>${t}</option>`).join('')}</select></div>${[...groups].map(([day,entries])=>`<section class="journal-day"><header><span>${day}</span><i></i><span>${entries.length} ${entries.length===1?'entry':'entries'}</span></header>${entries.map((c,i)=>`<article class="journal-entry"><div class="entry-margin"><span>${R.date(c.updated,{hour:'2-digit',minute:'2-digit'})}</span><i></i></div><div class="entry-page"><div class="entry-top"><span>${E(c.project)} <i>/</i> ${E(c.type)}</span>${R.bookmark(c)}</div><button class="entry-title" data-open="${E(c.id)}"><h2>${E(c.title)}</h2></button><p class="journal-prose">${E(c.tried||'A new thread, waiting to unfold.')}</p><div class="journal-next"><span>Next time →</span><p>${E(c.next)}</p></div>${c.blocked?`<div class="journal-blocked"><b>A loose end.</b> ${E(c.blocked)}</div>`:''}<div class="entry-bottom"><span>${I('branch')}<code>${E(c.branch||'No branch')}</code></span>${R.btn(`Continue this entry ${I('arrow')}`,'edit','text-btn',`data-id="${E(c.id)}"`)}</div><details class="journal-details"><summary>${I('file')}References & ${c.history.length} earlier checkpoint${c.history.length===1?'':'s'}</summary>${R.files(c)}${c.history.map(h=>`<div class="checkpoint"><time>${R.date(h.at,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</time><p>${E(h.tried)}</p><p><b>Next:</b> ${E(h.next)}</p></div>`).join('')}${!c.files.length&&!c.links&&!c.history.length?'<p class="muted small">No references or earlier checkpoints yet.</p>':''}</details></div></article>`).join('')}</section>`).join('')||R.empty('A fresh page.','No entries match this view. Start a new one, or change the filters.')}<div class="journal-end"><span>•</span><p>That’s the story so far.</p>${R.newButton('Leave the next entry')}</div></section><aside class="journal-right"><span class="mono">ON THIS PAGE</span><span class="journal-issue">No. ${String(cards.length).padStart(2,'0')}</span><p>${E(R.scopeTitle())}</p><div class="journal-key"><i></i>Every note is a<br>way back in.</div></aside></main></div>`;
};
R.focus = () => {
 const cards=R.cards(),c=R.current(),others=cards.filter(x=>x.id!==c?.id);
 return `<div class="focus-layout"><header class="focus-header">${R.logo(true)}<span class="mono">A LITTLE ROOM TO THINK</span><div>${R.btn(`${I('info')}The idea`,'research','text-btn')}${R.btn(I('folder'),'organize','icon-btn','aria-label="Organize projects and folders"')}${R.btn(I('export'),'backup','icon-btn','aria-label="Export and backup"')}</div></header><main id="main" class="focus-main"><section class="focus-left"><div class="focus-kicker"><i></i>YOU DON’T HAVE TO HOLD IT ALL.</div><h1>One thing.<br><em>Then the next.</em></h1><p>Put down the mental tabs.<br>Start with one thread.</p><div class="focus-selector">${R.projectSelect()}<select data-scope-select aria-label="Choose threads"><option value="all" ${R.ui.scope==='all'?'selected':''}>Active threads</option><option value="saved" ${R.ui.scope==='saved'?'selected':''}>Bookmarked</option><option value="archive" ${R.ui.scope==='archive'?'selected':''}>Archived</option></select></div>${R.ui.project?`<div class="focus-folder-filter">${R.folderSelect()}</div>`:''}${R.search('Find the thread you need…')}<div class="focus-orbit" aria-hidden="true"><svg viewBox="0 0 300 140"><path d="M10 120C120 120 100 20 200 20h75"/><path d="m260 5 16 15-16 15"/><path d="M10 100C100 100 80 0 185 0" stroke-dasharray="3 7"/><circle cx="10" cy="120" r="5"/></svg></div><div class="focus-bottom-note"><span>NO STREAKS. NO SCORE.</span><p>Just a place to leave your thinking.</p></div></section><section class="focus-right">${c?`<div class="focus-paper"><div class="focus-paper-top"><span>${R.ui.focusStarted?'YOU’RE IN THIS THREAD':'YOUR NEXT PLACE TO START'}</span>${R.bookmark(c)}</div><div class="focus-project">${R.projectMark(c.project)}${E(c.project)}<span> / ${E(c.type)}</span></div><h2>${E(c.title)}</h2><div class="focus-next"><span>THE NEXT STEP</span><p>${E(c.next)}</p></div><details class="focus-context" ${R.ui.focusStarted?'open':''}><summary>${I('lines')}Catch me up<span>${I('down')}</span></summary><div><h3>Last thing tried</h3><p>${E(c.tried||'No previous attempt recorded.')}</p>${c.blocked?`<h3>Blocked by</h3><p>${E(c.blocked)}</p>`:''}${R.files(c)}<div class="focus-branch">${I('branch')}${E(c.branch||'No branch reference')}</div></div></details><div class="focus-paper-actions">${R.ui.focusStarted?R.btn(`Leave a checkpoint ${I('arrow')}`,'edit','btn primary',`data-id="${E(c.id)}"`):R.btn(`I’ve got the context ${I('arrow')}`,'start-focus','btn primary',`data-id="${E(c.id)}"`)}${R.btn('Full handoff','open','text-btn',`data-id="${E(c.id)}"`)}</div><div class="focus-paper-foot">${R.status(c)}<span>Left ${R.age(c.updated)}</span></div></div>`:R.empty('A clear head. A new thread.','Nothing matches this view. Leave yourself a starting point.')}<div class="focus-queue-heading"><span>WAITING IN THE WINGS</span><span>${others.length} threads</span></div><div class="focus-queue">${others.map((item,i)=>`<button data-select="${E(item.id)}"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${E(item.title)}</strong><small>${E(item.project)} · ${E(item.type)}</small></div>${I('arrow')}</button>`).join('')||'<p class="muted small">Nothing else asking for your attention.</p>'}</div>${R.btn(`${I('plus')}Leave a different thread`,'new','focus-new')}</section></main></div>`;
};
R.switcher = () => `<div class="switcher-intro"><span class="switcher-dot"></span><span>FIVE WAYS TO RELAY</span></div><div class="switcher-numbers" role="group" aria-label="Prototype number">${R.modes.map((mode,i)=>`<button data-mode="${i+1}" class="${R.mode===i+1?'active':''}" aria-label="Prototype ${i+1}: ${mode.name}" aria-pressed="${R.mode===i+1}"><span>${i+1}</span><small>${mode.name}</small></button>`).join('')}</div><div class="switcher-description"><strong>${R.modes[R.mode-1].name}</strong><span>${R.modes[R.mode-1].description}</span></div><button class="switcher-info" data-action="compare" aria-label="Compare the five approaches">${I('info')}</button>`;
R.render = () => {
 const active=document.activeElement, isSearch=active?.hasAttribute('data-search'),position=isSearch?active.selectionStart:null;
 document.body.dataset.prototype=R.mode;
 document.querySelector('#app').innerHTML=[null,R.desk,R.index,R.board,R.journal,R.focus][R.mode]();
 document.querySelector('#prototype-switcher').innerHTML=R.switcher();
 if(isSearch){const input=document.querySelector('[data-search]');input?.focus();input?.setSelectionRange(position,position);}
};
